"use client";

import { useRef, useState } from "react";
import { motion } from "motion/react";

export function ConfettiButtonTailwind({ label = "Celebrate", count = 16 }) {
  const [bursts, setBursts] = useState<number[]>([]);
  const nextId = useRef(0);
  const fire = () => {
    const id = nextId.current++;
    setBursts((b) => [...b, id]);
    setTimeout(() => setBursts((b) => b.filter((x) => x !== id)), 1000);
  };
  return (
    <motion.button type="button" onClick={fire} whileTap={{ scale: 0.92 }} className="relative rounded-lg bg-zinc-100 px-5 py-2.5 text-sm font-medium text-zinc-950">
      {label}
      {bursts.map((id) => (
        <span key={id} aria-hidden className="pointer-events-none absolute left-1/2 top-1/2">
          {Array.from({ length: count }, (_, i) => {
            const a = (i / count) * Math.PI * 2;
            const d = 70 * (0.85 + (i % 3) * 0.3);
            return (
              <motion.span
                key={i}
                className={"absolute -left-1 -top-1 h-2 w-2 rounded-sm " + (i % 2 ? "bg-sky-400" : "bg-violet-400")}
                initial={{ x: 0, y: 0, opacity: 1, rotate: 0 }}
                animate={{ x: Math.cos(a) * d, y: Math.sin(a) * d, opacity: 0, rotate: 270 }}
                transition={{ duration: 0.9, ease: "easeOut" }}
              />
            );
          })}
        </span>
      ))}
    </motion.button>
  );
}
